"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["49721"],{5143(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.retificacao.ciclo_novo_de_item_sem_preliminar_aberto","status":422,"titulo":"O ciclo novo declarado n\xe3o tem resultado preliminar publicado com o ciclo aberto"},"descricao":{"codigo":"uniplus.selecao.retificacao.ciclo_novo_de_item_sem_preliminar_aberto","requisitos":["UNI-REQ-0157","UNI-REQ-0282"],"oQueAconteceu":["A retifica\xe7\xe3o que muda a regra ou os dados de entrada de um resultado preliminar j\xe1 publicado exige um novo resultado preliminar, em novo ciclo, antes do definitivo. O pedido de retifica\xe7\xe3o declara os itens que ter\xe3o novo ciclo, e um dos itens declarados n\xe3o tem resultado preliminar publicado com o ciclo ainda aberto.","Isso acontece quando o preliminar do item ainda n\xe3o foi publicado, quando o resultado definitivo que fecha o ciclo j\xe1 foi publicado, ou quando o item n\xe3o existe na vers\xe3o publicada vigente. A recusa \xe9 **422**, n\xe3o aponta campo, e a mensagem diz que o ciclo declarado n\xe3o tem preliminar publicado com o ciclo aberto; ela n\xe3o identifica o item.","Se houver mais de um problema na retifica\xe7\xe3o, as recusas s\xe3o devolvidas juntas, e as de ciclo n\xe3o declarado v\xeam antes destas."],"comoResolver":["Retire do pedido de retifica\xe7\xe3o o item declarado como novo ciclo que n\xe3o tem preliminar publicado com o ciclo aberto. Se o definitivo j\xe1 foi publicado, o ciclo est\xe1 encerrado e a retifica\xe7\xe3o n\xe3o o reabre. Se o item deveria existir, confira com a equipe do processo se o preliminar dele foi publicado."]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Retificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);